+            <span class="icon" aria-hidden="true"></span>
+          </button>
+          <div
+            class="answer"
+            id="${answerId}"
+            role="region"
+            aria-labelledby="${questionId}"
+          >
+            <div class="answer-inner">
+              <p>${item.answer}</p>
+            </div>
+          </div>
+        </div>
+      `;
+    }
+
+    function FAQList() {
+      return `
+        <section class="details" aria-label="Cat FAQ questions and answers">
+          ${faqs.map(FAQItem).join("")}
+        </section>
+      `;
+    }
+
+    function App() {
+      return `
+        ${Header()}
+        ${FAQList()}
+        <p class="footer-note">Tap a question to expand it. Tap again to collapse it.</p>
+      `;
+    }
+
+    function render() {
+      document.getElementById("root").innerHTML = App();
+      document.querySelectorAll(".question").forEach((button) => {
+        button.addEventListener("click", () => {
+          const index = Number(button.dataset.index);
+          state.openIndex = state.openIndex === index ? null : index;
+          render();
+        });
+      });
+    }
+
+    render();
+  </script>
+</body>
+</html>
*** End Patch
